import java.io.*; import java.util.*; import java.util.stream.*; import static java.util.stream.Collectors.toList; class Result { public static List<String> bomberMan(int n, List<String> grid) { int r = grid.size(); int c = grid.get(0).length(); if (n <= 1) return grid; if (n % 2 == 0) { List<String> full = new ArrayList<>(); for (int i = 0; i < r; i++) full.add("O".repeat(c)); return full; } char[][] state1 = detonate(grid, r, c); if (n % 4 == 3) return toStringList(state1, r, c); char[][] state2 = detonate(state1, r, c); return toStringList(state2, r, c); } private static char[][] detonate(List<String> grid, int r, int c) { char[][] next = new char[r][c]; for (int i = 0; i < r; i++) Arrays.fill(next[i], 'O'); for (int i = 0; i < r; i++) { for (int j = 0; j < c; j++) { if (grid.get(i).charAt(j) == 'O') { next[i][j] = '.'; if (i > 0) next[i - 1][j] = '.'; if (i < r - 1) next[i + 1][j] = '.'; if (j > 0) next[i][j - 1] = '.'; if (j < c - 1) next[i][j + 1] = '.'; } } } return next; } private static char[][] detonate(char[][] grid, int r, int c) { List<String> list = new ArrayList<>(); for (char[] row : grid) list.add(new String(row)); return detonate(list, r, c); } private static List<String> toStringList(char[][] grid, int r, int c) { List<String> res = new ArrayList<>(); for (int i = 0; i < r; i++) res.add(new String(grid[i])); return res; } } public class Solution { public static void main(String[] args) throws IOException { BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(System.in)); BufferedWriter bufferedWriter = new BufferedWriter(new FileWriter(System.getenv("OUTPUT_PATH"))); String[] firstMultipleInput = bufferedReader.readLine().replaceAll("\\s+$", "").split(" "); int r = Integer.parseInt(firstMultipleInput[0]); int c = Integer.parseInt(firstMultipleInput[1]); int n = Integer.parseInt(firstMultipleInput[2]); List<String> grid = IntStream.range(0, r).mapToObj(i -> { try { return bufferedReader.readLine(); } catch (IOException ex) { throw new RuntimeException(ex); } }).collect(toList()); List<String> result = Result.bomberMan(n, grid); bufferedWriter.write(result.stream().collect(Collectors.joining("\n")) + "\n"); bufferedReader.close(); bufferedWriter.close(); } }